// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ECDSA, SafeTransferLib} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(
        bool isCall,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address taker
    ) public {
        // admissible domain: keep it wide
        duration = bound(duration, 1, 9_999 days);
        strike = bound(strike, 1, type(uint128).max);
        premium = bound(premium, 1, type(uint128).max);
        vm.warp(1000);
        expiration = bound(expiration, block.timestamp + 1, block.timestamp + 30 days);
        vm.assume(taker != address(0) && taker.code.length == 0 && taker != address(c));

        // adversarial maker: contract counterparty that signs via ERC-1271 and whose
        // token-side transferFrom always succeeds (baseAsset must have code)
        MakerERC1271 maker = new MakerERC1271();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: true,
            baseAsset: address(maker),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = new bytes(0);

        vm.prank(taker);
        c.fillOrder(order, signature, floorAssetTokenIds);

        bytes32 orderHash = c.hashOrder(order);

        // GENERAL RULE: after a successful fill, the long position's expiration
        // stored by fillOrder equals block.timestamp + order.duration.
        assertTrue(
            c.positionExpirations(uint256(orderHash)) == block.timestamp + duration
        );
    }
}

contract MakerERC1271 {
    // ERC-1271: accepts any signature so the fuzzer doesn't need ECDSA keys
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    // SafeTransferLib calls transferFrom(0x23b872dd) on the baseAsset; always succeed
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
